package cz.halloween.core;
import java.time.LocalDate;import java.time.ZoneId;import java.util.List;import java.util.Random;import java.util.UUID;import org.bukkit.ChatColor;import org.bukkit.Material;import org.bukkit.command.Command;import org.bukkit.command.CommandExecutor;import org.bukkit.command.CommandSender;import org.bukkit.command.TabCompleter;import org.bukkit.entity.EntityType;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.EventPriority;import org.bukkit.event.Listener;import org.bukkit.event.block.BlockBreakEvent;import org.bukkit.event.entity.EntityDeathEvent;
public final class DailyQuestManager implements Listener,CommandExecutor,TabCompleter{
 private record Task(String id,String title,String description,int target){} private static final List<Task>TASKS=List.of(new Task("zombies","Lov na nemrtvé","Zabij 8 zombie.",8),new Task("skeletons","Kostlivci po setmění","Zabij 8 kostlivců.",8),new Task("iron","Železná zásoba","Vytěž 16 železných rud.",16),new Task("pumpkins","Dýňová sklizeň","Rozbij 12 dýní.",12));
 private final HalloweenCore plugin;private final Random random=new Random();public DailyQuestManager(HalloweenCore p){plugin=p;}
 @Override public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage(ChatColor.RED+"Příkaz /quest může použít jen hráč.");return true;}if(!plugin.getConfig().getBoolean("daily-quest.enabled",true)){p.sendMessage(ChatColor.RED+"Denní úkoly jsou vypnuté.");return true;}String today=today(),path=path(p.getUniqueId());if(!today.equals(plugin.getPlayerData().getString(path+".date","")))assign(p,path,today);show(p,path);return true;}
 private void assign(Player p,String path,String today){String old=plugin.getPlayerData().getString(path+".id","");List<Task> opts=TASKS.stream().filter(t->!t.id().equals(old)).toList();Task t=opts.isEmpty()?TASKS.get(random.nextInt(TASKS.size())):opts.get(random.nextInt(opts.size()));plugin.getPlayerData().set(path+".date",today);plugin.getPlayerData().set(path+".id",t.id());plugin.getPlayerData().set(path+".title",t.title());plugin.getPlayerData().set(path+".description",t.description());plugin.getPlayerData().set(path+".target",t.target());plugin.getPlayerData().set(path+".progress",0);plugin.getPlayerData().set(path+".completed",false);plugin.savePlayerData();p.sendMessage(ChatColor.DARK_PURPLE+"☾ "+ChatColor.GOLD+"Dostal jsi nový denní úkol!");}
 private void show(Player p,String path){String title=plugin.getPlayerData().getString(path+".title","Denní úkol");int progress=plugin.getPlayerData().getInt(path+".progress",0),target=Math.max(1,plugin.getPlayerData().getInt(path+".target",1));if(plugin.getPlayerData().getBoolean(path+".completed",false)){p.sendMessage(ChatColor.GREEN+"Dnešní úkol už máš hotový: "+title);return;}int reward=Math.max(0,plugin.getConfig().getInt("daily-quest.reward-fragments",1));p.sendMessage(ChatColor.DARK_PURPLE+"╔════════ H A L L O W E E N ════════╗");p.sendMessage(ChatColor.GOLD+"☾ ÚKOL: "+ChatColor.YELLOW+title);p.sendMessage(ChatColor.GRAY+plugin.getPlayerData().getString(path+".description",""));p.sendMessage(ChatColor.GRAY+"Postup: "+ChatColor.GOLD+Math.min(progress,target)+ChatColor.GRAY+"/"+ChatColor.GOLD+target);p.sendMessage(ChatColor.DARK_GRAY+"Odměna: "+ChatColor.GOLD+reward+(reward==1?" fragment":" fragmentů"));p.sendMessage(ChatColor.DARK_PURPLE+"╚══════════════════════════════════╝");}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void onMobKilled(EntityDeathEvent e){Player p=e.getEntity().getKiller();if(p==null)return;if(e.getEntityType()==EntityType.ZOMBIE)increment(p,"zombies");else if(e.getEntityType()==EntityType.SKELETON)increment(p,"skeletons");}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void onBlockBreak(BlockBreakEvent e){Material m=e.getBlock().getType();if(m==Material.IRON_ORE||m==Material.DEEPSLATE_IRON_ORE)increment(e.getPlayer(),"iron");else if(m==Material.PUMPKIN||m==Material.CARVED_PUMPKIN)increment(e.getPlayer(),"pumpkins");}
 private void increment(Player p,String id){if(!plugin.getConfig().getBoolean("daily-quest.enabled",true))return;String path=path(p.getUniqueId());if(!today().equals(plugin.getPlayerData().getString(path+".date",""))||!id.equals(plugin.getPlayerData().getString(path+".id",""))||plugin.getPlayerData().getBoolean(path+".completed",false))return;int target=Math.max(1,plugin.getPlayerData().getInt(path+".target",1)),progress=Math.min(target,Math.max(0,plugin.getPlayerData().getInt(path+".progress",0))+1);plugin.getPlayerData().set(path+".progress",progress);if(progress>=target){plugin.getPlayerData().set(path+".completed",true);long reward=Math.max(0L,plugin.getConfig().getLong("daily-quest.reward-fragments",1));String b="players."+p.getUniqueId()+".fragments";long bal=Math.max(0L,plugin.getPlayerData().getLong(b,0));plugin.getPlayerData().set(b,bal>Long.MAX_VALUE-reward?Long.MAX_VALUE:bal+reward);p.sendMessage(ChatColor.GREEN+"Splnil jsi denní úkol! "+ChatColor.GOLD+"+"+reward+(reward==1?" fragment.":" fragmentů."));}else p.sendMessage(ChatColor.GRAY+"Denní úkol: "+ChatColor.YELLOW+progress+"/"+target);plugin.savePlayerData();}
 private String path(UUID id){return "players."+id+".daily-quest";}private String today(){return LocalDate.now(ZoneId.of("Europe/Prague")).toString();}@Override public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){return List.of();}
}